window.I18N = (() => {
  'use strict';
  const LANGS = ['uk', 'en', 'es'], NAMES = { uk: 'Українська', en: 'English', es: 'Español' }, LOC = { uk: 'uk-UA', en: 'en-US', es: 'es-ES' };
  function detect() {
    const ls = (navigator.languages && navigator.languages.length ? navigator.languages : [navigator.language || 'en']).map(s => String(s).toLowerCase().slice(0, 2));
    for (const l of ls) { if (l === 'uk' || l === 'ru' || l === 'be') return 'uk'; if (l === 'es') return 'es'; if (l === 'en') return 'en'; }
    return 'en';
  }
  let lang = 'en';
  const fill = (s, v) => v ? s.replace(/\{(\w+)\}/g, (m, k) => v[k] != null ? v[k] : m) : s;
  function t(k, v) { const s = (BH_STR[lang] && BH_STR[lang][k]) ?? BH_STR.en[k] ?? BH_STR.uk[k]; return s == null ? k : fill(s, v); }
  function apply(root) {
    (root || document).querySelectorAll('[data-i]').forEach(e => { e.textContent = t(e.getAttribute('data-i')); });
    (root || document).querySelectorAll('[data-ih]').forEach(e => { e.innerHTML = t(e.getAttribute('data-ih')); });
    document.documentElement.lang = lang;
  }
  return {
    LANGS, NAMES, detect, t, apply,
    get lang() { return lang; },
    set(l) { lang = LANGS.includes(l) ? l : detect(); return lang; },
    num: n => Number(n).toLocaleString(LOC[lang]),
    lvName(id, uk) { const e = BH_LV[id]; return lang === 'uk' || !e ? uk : e[lang][0]; },
    lvHint(id, uk) { const e = BH_LV[id]; return lang === 'uk' || !e ? uk : e[lang][1]; },
    secName(s) { if (/^test\d+$/.test(s.id)) return t('S.test.n', { k: s.k + 1 }); const v = BH_STR[lang]['S.' + s.id + '.n']; return v || s.n; },
    secDesc(s) { if (/^test\d+$/.test(s.id)) return t('S.test.d'); const v = BH_STR[lang]['S.' + s.id + '.d']; return v || s.d; },
    fact(id) { const f = window.BH_FACTS && BH_FACTS[id]; if (!f) return null; const x = f[lang] || f.en; return { id, n: f.n, boss: f.boss, src: f.src, url: f.url, title: x[0], text: x[1] }; },
  };
})();
